      col(b.id).byId.set(r.id, r);
      if (S.drawer && S.drawer.rec && S.drawer.rec.id === rec.id) { S.drawer.rec = r; S.drawer.draft = JSON.parse(JSON.stringify(r.data)); S.drawer.dirty = false; renderDrawer(); }
