        if (a && a.gone) out.push({ key: 'v:' + b.id + ':' + rec.id + ':' + i, virtual: true, b, rec, idx: i, a, kind: a.t, label: a.t === 'file' ? ((fileMeta(a.id) || {}).name || a.name || 'File') : (a.title || hostOf(a.url)), deletedAt: a.goneAt || rec.updatedAt, deletedByName: (person(a.goneBy) || {}).name || '' });
